	public JsonObject serialize()
	{
		JsonObject jsonObj = new JsonObject();
		jsonObj.addProperty(Constants.JSON.BLOCK, getEntry());

		return jsonObj;
	}
}

package wayoftime.bloodmagic.common.recipe.serializer;

